import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums for single main items (base + 10% first insurance + 5G fee) ---
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("single sword -> base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("single amulet -> base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single staff -> base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("single potion -> base 40 G + 4 G first insurance + 5 G fee = 49 G");

  // --- Component base premiums (building blocks) ---
  it.todo("2 runes -> 50 G base premium (+ first insurance + fee)");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (no block - block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium");

  // --- 'Alike' components ---
  it.todo("2 runes + 1 moonstone -> 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> curse adds 50% of cursed sword base only");
  it.todo("item-specific modifiers apply to affected item; policy-wide to policy base");

  // --- Modifier thresholds ---
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 5 and cursed -> both surcharges apply");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> 198 G (rounded up, in MHPCO favor)");

  // --- Integration: newcomer with cursed sword ---
  it.todo("newcomer cursed sword (0 years) -> premium 165 G");

  // --- Integration: long-standing customer's second contract ---
  it.todo("long-standing customer 2nd contract cursed enchanted sword -> premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword, damage 500 G -> payout 400 G (full minus deductible)");
  it.todo("rune damage 200 G -> payout 100 G (full minus deductible)");

  // --- Claim: high enchantment clause ---
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50% then deductible)");

  // --- Claim: dragon material clause ---
  it.todo("dragon sword enchantment 5, damage 800 G -> payout 700 G (full then deductible)");

  // --- Claim: both clauses, 50% wins ---
  it.todo("dragon sword enchantment 9, damage 1000 G -> payout 400 G (50% wins)");
  it.todo("dragon sword enchantment 8, damage 1000 G -> payout 400 G (high-ench then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword 500 + amulet 300 -> payout 600 G (deductible per item)");

  // --- Claim: payout rounding ---
  it.todo("payout yielding 350.5 G -> 350 G (rounded down, in MHPCO favor)");

  // --- Multiple items of same type ---
  it.todo("policy covers two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damages both reimbursed with own deductible");
  it.todo("more damage entries of a type than covered -> non-zero exit (rejected)");

  // --- Cap exhaustion ---
  it.todo("cursed sword cap 2000 G based on unmodified insurance value");
  it.todo("two successive 1500 G claims -> 1400 G then 600 G (cap exhaustion)");

  // --- Error / edge cases ---
  it.todo("quote with unknown item type -> non-zero exit, error to stderr");
  it.todo("claim references item not in policy -> non-zero exit, error to stderr");
  it.todo("claim damage amount -200 -> non-zero exit, error to stderr");
});

