const PROCESSING_FEE = 5;

interface QuoteStep {
  op: "quote";
  items: { type: string }[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => {
    let base = 0;
    for (const item of step.items) {
      if (item.type === "sword") base += 100;
    }
    const firstInsurance = base * 0.1;
    return { premium: base + firstInsurance + PROCESSING_FEE };
  });
  return { results };
};

