interface Customer {
  yearsWithMHPCO: number;
}

const stepPremium = (step: QuoteStep, customer: Customer): number => {
  const basePremium = policyBasePremium(step.items);
  const firstInsurance = basePremium * FIRST_INSURANCE_RATE;
  const surcharges = policySurcharges(step.items);
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
      ? basePremium * LOYALTY_DISCOUNT_RATE
      : 0;
  return (
    basePremium + surcharges + firstInsurance - loyaltyDiscount + PROCESSING_FEE
  );
};

export const processScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: stepPremium(step, scenario.customer),
  }));
  return { results };
};

