const validateClaim = (policy: QuoteStep, incident: Incident): void => {
  const insuredCounts = countByType(policy.items);
  const damageCounts = new Map<string, number>();
  for (const damage of incident.damages) {
    damageCounts.set(
      damage.itemType,
      (damageCounts.get(damage.itemType) ?? 0) + 1,
    );
  }
  for (const [type, count] of damageCounts) {
    if (count > (insuredCounts.get(type) ?? 0)) {
      throw new Error(
        `claim damages ${count} ${type}(s) but policy covers fewer`,
      );
    }
  }
};

const processClaim = (
  claim: ClaimStep,
  steps: Step[],
): { payout: number; remainingCap: number } => {
  const policy = steps[claim.policy] as QuoteStep;
  validateClaim(policy, claim.incident);
  const cap = policyInsuranceSum(policy.items) * CAP_MULTIPLIER;
  const payout = roundPayoutDown(claimPayout(policy, claim.incident));
  return { payout, remainingCap: cap - payout };
};

